@SpringBootApplication
public class Application {
    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }

    // Topic configuration
    @Bean
    public NewTopic topic() {
        return TopicBuilder.name("InfyRail_C_To_D").partitions(6).replicas(1).build();
    }

    // Producer logic - sends Speed and Brake Efficiency every 2 seconds
    @Bean
    public ApplicationRunner sendMessage(KafkaTemplate<String, String> template) {
        return args -> {
            for (;;) {
                template.send("InfyRail_C_To_D", "Speed", String.valueOf(Math.round(Math.random() * 1000)));
                template.send("InfyRail_C_To_D", "BrakeEfficiency", String.valueOf(Math.round(Math.random() * 100)));
                System.out.println("Sender Module: Speed and braking efficiency information sent successfully");
                Thread.sleep(2000);
            }
        };
    }

    // Consumer logic using ConsumerRecord
    @KafkaListener(id = "IRC2D_1", topics = "InfyRail_C_To_D")
    public void listenToTopics(ConsumerRecord<String, String> record) {
        System.out.println("Receiver Module");
        System.out.println("Key:- " + record.key());
        System.out.println("Value:- " + record.value());
        System.out.println("Partition:- " + record.partition());
        System.out.println("Timestamp:- " + record.timestamp());
        System.out.println("Topic:- " + record.topic());
        System.out.println("Offset:- " + record.offset());
        System.out.println("--------------------------------------------");
    }
}

